   5  * Custom error class for wrapping Firebase errors to be identified easily.
   6  */
   7 export class CustomFirebaseError extends Error {
   8   public code: string;
   9   public originalError?: any;
  10 
  11   constructor(code: string, message: string, originalError?: any) {
  12     super(message);
  13     this.code = code;
  14     this.name = 'CustomFirebaseError';
  15     this.originalError = originalError;
  16     Object.setPrototypeOf(this, CustomFirebaseError.prototype);
