  20 /**
  21  * Checks if an error is a Firebase Admin or Client SDK error.
  22  * @param error The error to check.
  23  * @returns True if the error has a 'code' property, which is characteristic of Firebase errors.
  24  */
  25 function isFirebaseError(error: any): error is AdminFirebaseError | ClientFirebaseError {
  26   return error && typeof error.code === 'string' && typeof error.message === 'string';
  27 }
  28 
  29 /**
  30  * Utility function to handle and normalize Firebase errors.
  31  * If the error is a known Firebase error, it's wrapped in a CustomFirebaseError.
  32  * @param error The caught error.
  33  * @returns A CustomFirebaseError if the error is from Firebase, otherwise returns the original error.
  34  */
  35 export function handleFirebaseError(error: any): CustomFirebaseError | any {
  36   if (isFirebaseError(error)) {
  37     let message = error.message;
  38     // Provide more user-friendly messages for common auth errors
  39     switch (error.code) {
  40       case 'auth/id-token-expired':
  41         message = 'Your session has expired. Please log in again.';
  42         break;
  43       case 'auth/user-not-found':
  44       case 'auth/wrong-password':
  45       case 'auth/invalid-credential':
  46       case 'auth/invalid-email':
  47         message = 'Invalid email or password.';
  48         break;
  49       case 'auth/email-already-exists':
  50         message = 'An account with this email address already exists.';
  51         break;
  52       case 'auth/weak-password':
  53         message = 'The password is too weak. It must be at least 6 characters long.';
  54         break;
  55     }
  56     return new CustomFirebaseError(error.code, message, error);
  57   }
  58   // If it's not a Firebase error, return it as-is to be handled by the next part of the chain.
  59   return error;
